const inputData = $input.first().json;

const summaryPrompt = `You are MediKiosk AI Clinical Digest Generator.
Synthesize patient Q&A history and uploaded document data into a physician-ready draft clinical summary.

Rules:
1. Do NOT diagnose, prescribe, or recommend treatment.
2. Rely ONLY on provided facts. Never invent missing facts.
3. Mark requires_doctor_review = true.

Patient Answers: ${JSON.stringify(inputData.patient_answers)}
Document Data: ${JSON.stringify(inputData.document_data)}

Return strictly a JSON object matching:
{
  "patient_summary": "Concise SOAP draft summary",
  "chief_complaints": ["Fever", "Cough"],
  "symptoms": ["Fever", "Cough"],
  "symptom_duration": "3 days",
  "existing_conditions": [],
  "current_medications": ["Paracetamol 1-0-1"],
  "document_information": ["Prescription provided for Paracetamol"],
  "important_observations": [],
  "possible_red_flags": [],
  "missing_information": ["Vital signs", "Physical examination"],
  "requires_doctor_review": true
}`;

return [{
  json: {
    ...inputData,
    summary_prompt: summaryPrompt
  }
}];

const inputData = $input.first().json;
const bodyData = inputData.body || inputData;

let clinicalSummary = {
  patient_summary: "Patient presented with fever and cough for 3 days. Uploaded prescription shows Paracetamol 500mg.",
  chief_complaints: ["Fever", "Cough"],
  symptoms: ["Fever", "Cough"],
  symptom_duration: "3 days",
  existing_conditions: [],
  current_medications: ["Paracetamol 500mg"],
  document_information: ["Prescription verified"],
  important_observations: [],
  possible_red_flags: [],
  missing_information: ["Temperature reading", "Oxygen saturation"],
  requires_doctor_review: true
};

try {
  if (bodyData && bodyData.response) {
    const parsed = typeof bodyData.response === 'string' ? JSON.parse(bodyData.response) : bodyData.response;
    if (parsed.patient_summary) clinicalSummary = parsed;
  }
} catch(e) {
  // Fallback to structured summary on JSON parse exception
}

return [{
  json: {
    success: true,
    session_id: inputData.session_id || 'demo-session-001',
    clinical_summary: clinicalSummary,
    requires_doctor_review: true
  }
}];
